import{_ as e,o as s,c as i,a2 as t}from"./chunks/framework.doxMM-x8.js";const k=JSON.parse('{"title":"快速开始","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/getting-started/quickstart","contentType":"guide","prev":{"text":"项目文档","link":"/docs/"},"next":{"text":"Lab 与资产库","link":"/guides/lab-viewer"}},"headers":[],"relativePath":"getting-started/quickstart.md","filePath":"getting-started/quickstart.md"}'),n={name:"getting-started/quickstart.md"};function l(p,a,r,h,d,o){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>启动 Node 服务与 Web，创建账户并打开持久 Lab。使用 Linux 或 Windows，以及仓库锁定的 <a href="https://github.com/CaiZongyuan/labworld/blob/2fef28c35afea44ae2018f0e4b6a3a18a96a2bf7/.node-version" target="_blank" rel="noreferrer">Node 24.18.0</a> 和 <a href="https://github.com/CaiZongyuan/labworld/blob/2fef28c35afea44ae2018f0e4b6a3a18a96a2bf7/package.json" target="_blank" rel="noreferrer">pnpm 11.17.0</a>。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/CaiZongyuan/labworld.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> labworld</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>命令从仓库根目录执行。服务先初始化嵌入数据库并恢复状态，再接入 HTTP。服务地址为 <code>http://127.0.0.1:3000</code>，Web 为 <code>http://127.0.0.1:5173</code>。重启后保留 <code>data/</code> 数据。启动输出提供开发进程所有权记录路径。</p><h2 id="打开应用" tabindex="-1">打开应用 <a class="header-anchor" href="#打开应用" aria-label="Permalink to &quot;打开应用&quot;">​</a></h2><ol><li>打开 <a href="http://127.0.0.1:5173/register" target="_blank" rel="noreferrer">http://127.0.0.1:5173/register</a>，使用 12–128 字符的密码注册。首个账户为 Owner，后续为 Member。</li><li>登录与注册后进入 Lab。新建 Lab，再打开其空间。</li><li>打开资产库，上传 GLB 并填写来源、许可与版本，等待校验。导入被拒绝后，前一个有效模型仍可使用。</li><li>注册 Entity，在 Lab 放置 Scene Node，保存布局后刷新。可以通过地址重新打开同一 Lab 与所选 Entity。</li><li>继续阅读 <a href="./../guides/lab-viewer">Lab 指南</a>、<a href="./../guides/server-world">World</a> 和 <a href="./../guides/server-devices">Devices</a>。用户与 Agent 共用保留的 API 和后端设备程序。</li></ol><p>共享首页保留在 <code>/</code>，设置与 API key 地址为 <code>/settings</code> 和 <code>/api-keys</code>。移除模块的旧书签显示不可用页面，并提供返回入口。</p><h2 id="验证与停服" tabindex="-1">验证与停服 <a class="header-anchor" href="#验证与停服" aria-label="Permalink to &quot;验证与停服&quot;">​</a></h2><p>保持开发运行，在另一个终端执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/live</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/ready</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/api/v1/system/status</span></span></code></pre></div><p>就绪后返回 HTTP 200 和 <code>x-request-id</code>，系统状态报告实际 schema。开发终端按 Ctrl+C，等待两个进程排空并关闭。持久数据保留。监督进程异常退出后，先用输出记录执行 <code>pnpm dev:recover &lt;ledger&gt;</code>，再重启。保留活跃服务与未知数据。</p><p>需要修改 Node 和 Web 设置时，将 <a href="https://github.com/CaiZongyuan/labworld/blob/2fef28c35afea44ae2018f0e4b6a3a18a96a2bf7/.env.example" target="_blank" rel="noreferrer">.env.example</a>复制为未跟踪的 <code>.env</code>。Node 入口命令加载此文件，Vite 从仓库根目录读取。参见<a href="./../reference/config">生成配置</a>和<a href="./../guides/server-foundation">独立目录与端口</a>。</p><p>停服备份、恢复到新目录或空目录，以及密码恢复，见<a href="./../guides/server-operations">服务运维</a>。忘记密码时使用运维 CLI。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:frontend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contracts:check</span></span></code></pre></div><p>浏览器检查与完整验证职责见<a href="./../testing/feedback-loop">开发与验证</a>。</p><hr><p>源码版本：<code>2fef28c35afe</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/2fef28c35afea44ae2018f0e4b6a3a18a96a2bf7/docs/getting-started/quickstart.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,17)])])}const g=e(n,[["render",l]]);export{k as __pageData,g as default};
